func TestReorgReplacesSuffixAndReportsDropped(t *testing.T) {
	index := chain(t,
		Block{Height: 1, Hash: "h1", Parent: "genesis"},
		Block{Height: 2, Hash: "h2", Parent: "h1"},
		Block{Height: 3, Hash: "h3", Parent: "h2"},
