	dropped, err := index.Reorg([]Block{
		{Height: 2, Hash: "h2b", Parent: "h1"},
		{Height: 3, Hash: "h3b", Parent: "h2b"},
		{Height: 4, Hash: "h4b", Parent: "h3b"},
	})
	if err != nil {
		t.Fatalf("reorg refused: %v", err)
	}
	if !reflect.DeepEqual(dropped, []int64{2, 3}) {
