186	// The counting and ordering semantics the regression rests on, asserted for
187	// each chain and cross-checked against the live index before and after the
188	// restore.
189	func TestRestoreQueryTxsFixtureSemanticsOnBothChains(t *testing.T) {
190		oldChain := restoreQueryOldChainBlocks()
191		newChain := restoreQueryNewChainBlocks()
192	
193		oldHits, oldBlocks := restoreFilteredHits(oldChain, restoreTxQuery.TxIDs)
194		wantOld := []TxHit{
195			{Height: 1, BlockHash: "h1", TxID: "x", Position: 0},
196			{Height: 1, BlockHash: "h1", TxID: "x", Position: 2},
197			{Height: 3, BlockHash: "h3", TxID: "y", Position: 1},
198			{Height: 4, BlockHash: "h4", TxID: "x", Position: 2},
199			{Height: 4, BlockHash: "h4", TxID: "y", Position: 3},
200			{Height: 4, BlockHash: "h4", TxID: "y", Position: 4},
201			{Height: 5, BlockHash: "h5", TxID: "y", Position: 0},
202		}
203		if !reflect.DeepEqual(oldHits, wantOld) {
204			t.Fatalf("old filtered hits=%v, want %v", oldHits, wantOld)
205		}
206		if oldBlocks != 4 {
207			t.Fatalf("old matched blocks=%d, want 4 (h1,h3,h4,h5)", oldBlocks)
208		}
209	
210		newHits, newBlocks := restoreFilteredHits(newChain, restoreTxQuery.TxIDs)
211		wantNew := []TxHit{
212			{Height: 1, BlockHash: "j1", TxID: "x", Position: 0},
213			{Height: 1, BlockHash: "j1", TxID: "y", Position: 1},
214			{Height: 4, BlockHash: "j4", TxID: "y", Position: 0},
215			{Height: 4, BlockHash: "j4", TxID: "y", Position: 1},
216			{Height: 4, BlockHash: "j4", TxID: "x", Position: 3},
217		}
218		if !reflect.DeepEqual(newHits, wantNew) {
219			t.Fatalf("new filtered hits=%v, want %v", newHits, wantNew)
220		}
221		if newBlocks != 2 {
222			t.Fatalf("new matched blocks=%d, want 2 (j1,j4)", newBlocks)
223		}
224	
225		// Setup invariants that make old/new/mixture answers distinguishable.
226		//
227		// Every overlap height carries different content under a different hash;
228		// a removed height holds an only-old match, and the shorter chain carries
229		// only-new matches. Restore replaces height 1 as well, so the chains
230		// share no block hash and no record is explainable by both chains.
231		if containsHit(newHits, TxHit{Height: 5, BlockHash: "h5", TxID: "y", Position: 0}) {
232			t.Fatal("removed-height match y@h5 must not exist on the new chain")
233		}
234		if !containsHit(oldHits, TxHit{Height: 5, BlockHash: "h5", TxID: "y", Position: 0}) {
235			t.Fatal("old chain must keep y@h5, the match confined to a removed height")
236		}
237		if !containsHit(newHits, TxHit{Height: 4, BlockHash: "j4", TxID: "y", Position: 1}) {
238			t.Fatal("new chain must keep its only-new y@j4#1 occurrence")
239		}
240		if containsHit(oldHits, TxHit{Height: 4, BlockHash: "j4", TxID: "y", Position: 1}) {
241			t.Fatal("j4 occurrence must not exist on the old chain")
242		}
243		// Duplicate matching ids survive with multiplicity, exact position, and
244		// the block hash of the observed chain.
245		if !containsHit(oldHits, TxHit{Height: 1, BlockHash: "h1", TxID: "x", Position: 2}) ||
246			!containsHit(newHits, TxHit{Height: 4, BlockHash: "j4", TxID: "y", Position: 1}) {
247			t.Fatal("duplicate in-block matching ids must be kept by occurrence")
248		}
249		requireOrdered(t, oldHits)
250		requireOrdered(t, newHits)
251	
252		// The three counts must not coincide on either chain, so correct records
253		// cannot mask statistics drawn from the wrong chain.
254		pageLen := int64(restoreTxPageSize)
255		for name, totals := range map[string][2]int64{
256			"old": {int64(len(oldHits)), oldBlocks},
257			"new": {int64(len(newHits)), newBlocks},
258		} {
259			if totals[0] == totals[1] || totals[0] == pageLen || totals[1] == pageLen {
260				t.Fatalf("%s chain setup: total=%d blocks=%d page=%d must all differ",
261					name, totals[0], totals[1], pageLen)
262			}
263		}
264		if int64(len(oldHits)) == int64(len(newHits)) || oldBlocks == newBlocks {
265			t.Fatal("old and new totals must differ so the complete answers are distinct")
266		}
267		// First pages leave matches unpaginated on both chains, and statistics
268		// span the whole range rather than the page.
269		if int64(len(literalRestoreTxOldFirstPage().Hits)) != pageLen ||
270			int64(len(literalRestoreTxNewFirstPage().Hits)) != pageLen {
271			t.Fatal("test setup: both literal first pages must be exactly one page long")
272		}
273	
274		// Oracle pages must equal the hand-derived literal pages.
275		if got := restoreReferenceTxPage(oldChain, restoreTxPageSize, 0); !reflect.DeepEqual(got, literalRestoreTxOldFirstPage()) {
276			t.Fatalf("old oracle page=%+v", got)
277		}
278		if got := restoreReferenceTxPage(newChain, restoreTxPageSize, 0); !reflect.DeepEqual(got, literalRestoreTxNewFirstPage()) {
279			t.Fatalf("new oracle page=%+v", got)
280		}
281	
282		// The oracle must match the live index on both complete chain states.
283		index := buildRestoreQueryOldChain(t)
284		live, err := index.QueryTxs(restoreTxQuery)
285		if err != nil {
286			t.Fatal(err)
287		}
288		if !reflect.DeepEqual(viewOf(live), viewOf(literalRestoreTxOldFirstPage())) {
289			t.Fatalf("live old-chain query=%+v, want literal old first page", live)
290		}
291		if live.NextCursor == "" {
292			t.Fatal("old first page over 7 matches with page size 3 must carry a cursor")
293		}
294	
295		if err := index.Restore(strings.NewReader(restoreTxNewSnapshot)); err != nil {
296			t.Fatalf("restore refused: %v", err)
297		}
298		if index.Tip != 4 {
299			t.Fatalf("tip after restore=%d, want 4", index.Tip)
300		}
301		live, err = index.QueryTxs(restoreTxQuery)
302		if err != nil {
303			t.Fatal(err)
304		}
305		if !reflect.DeepEqual(viewOf(live), viewOf(literalRestoreTxNewFirstPage())) {
306			t.Fatalf("live new-chain query=%+v, want literal new first page", live)
307		}
308		if live.NextCursor == "" {
309			t.Fatal("new first page over 5 matches with page size 3 must carry a cursor")
310		}
311	}
312	
313	// Plain before/after behavior through the public API: after a successful
314	// restore the first page reflects only the snapshot chain.
315	func TestQueryTxsBeforeAndAfterRestore(t *testing.T) {
316		index := buildRestoreQueryOldChain(t)
317	
318		before, err := index.QueryTxs(restoreTxQuery)
319		if err != nil {
320			t.Fatal(err)
321		}
322		if !reflect.DeepEqual(viewOf(before), viewOf(literalRestoreTxOldFirstPage())) {
323			t.Fatalf("pre-restore page=%+v, want old first page", before)
324		}
325	
326		if err := index.Restore(strings.NewReader(restoreTxNewSnapshot)); err != nil {
327			t.Fatalf("restore refused: %v", err)
328		}
329		if index.Tip != 4 {
330			t.Fatalf("tip=%d, want restored tip 4", index.Tip)
331		}
332	
333		after, err := index.QueryTxs(restoreTxQuery)
334		if err != nil {
335			t.Fatal(err)
336		}
337		if !reflect.DeepEqual(viewOf(after), viewOf(literalRestoreTxNewFirstPage())) {
338			t.Fatalf("post-restore page not wholly on the new chain:\n%+v", after)
339		}
340		// No residue of the replaced chain: removed heights and hashes are gone,
341		// and no removed-height match leaks into the answer or the statistics.
342		for _, height := range []int64{5, 6} {
343			if _, ok := index.Blocks[height]; ok {
344				t.Fatalf("replaced height %d still present", height)
345			}
346		}
347		for _, gone := range []string{"h1", "h2", "h3", "h4", "h5", "h6"} {
348			if _, ok := index.ByHash[gone]; ok {
349				t.Fatalf("replaced hash %s still indexed", gone)
350			}
351		}
352		for _, hit := range after.Hits {
353			if hit.Height > 4 || strings.HasPrefix(hit.BlockHash, "h") {
354				t.Fatalf("removed-chain record leaked into post-restore page: %+v", hit)
355			}
356		}
357		if after.ToHeight != 4 || after.TotalMatches != 5 || after.MatchedBlocks != 2 {
358			t.Fatalf("old tip or statistics leaked into post-restore page: %+v", after)
359		}
360	}
361	
362	// While the snapshot is still being read the restore holds no lock: a first
363	// page issued then completes on the complete OLD chain, and the fragments
364	// already consumed by the parser have no effect on it. Once the read
365	// finishes and the replacement lands, the same query answers from the new
366	// chain.
367	func TestQueryTxsWhileRestoreStillReading(t *testing.T) {
368		index := buildRestoreQueryOldChain(t)
369		// Park the read just before the second block object: the first snapshot
370		// block has already been consumed, but the replacement is nowhere near
371		// applied and Restore holds no lock.
372		reader := newGatedReader(t, restoreTxNewSnapshot, `{"height":2`)
373	
374		restoreDone := make(chan error, 1)
375		go func() {
376			restoreDone <- index.Restore(reader)
377		}()
378		<-reader.entered
379	
380		page, err := index.QueryTxs(restoreTxQuery)
381		if err != nil {
382			t.Fatalf("query during snapshot read failed: %v", err)
383		}
384		if !reflect.DeepEqual(viewOf(page), viewOf(literalRestoreTxOldFirstPage())) {
385			t.Fatalf("query during snapshot read must see the complete old chain:\n%+v", page)
386		}
387		select {
388		case err := <-restoreDone:
389			t.Fatalf("restore returned while its input was still gated: %v", err)
390		default:
391		}
392	
393		close(reader.release)
394		if err := <-restoreDone; err != nil {
395			t.Fatalf("restore after release failed: %v", err)
396		}
397		page, err = index.QueryTxs(restoreTxQuery)
398		if err != nil {
399			t.Fatal(err)
400		}
401		if !reflect.DeepEqual(viewOf(page), viewOf(literalRestoreTxNewFirstPage())) {
402			t.Fatalf("query after completed restore must see the complete new chain:\n%+v", page)
403		}
404	}
405	
406	// restoreQueryHooks are deterministic rendezvous for the QueryTxs/Restore
407	// overlap tests: a parked first page holds the lock with the tip-bound
408	// height already resolved; a parked restore has the new chain fully
409	// installed but has not returned and still holds the lock.
410	type restoreQueryHooks struct {
411		firstParked  chan struct{}
412		releaseFirst chan struct{}
413	
414		restoreParked  chan struct{}
415		releaseRestore chan struct{}
416	
417		allowedRestoreTip int64
418		firstOnce         sync.Once
419		restoreOnce       sync.Once
420	}
421	
422	func installRestoreQueryHooks(t *testing.T, parkFirst bool, restoreTip int64) *restoreQueryHooks {
423		t.Helper()
424		h := &restoreQueryHooks{
425			allowedRestoreTip: restoreTip,
426			restoreParked:     make(chan struct{}),
427			releaseRestore:    make(chan struct{}),
428		}
429		if parkFirst {
430			h.firstParked = make(chan struct{})
431			h.releaseFirst = make(chan struct{})
432		}
433		queryTxsHookLocked = func(from, to int64, continuation bool) {
434			if continuation || h.firstParked == nil {
435				return // only first pages participate in the rendezvous
436			}
437			if from != 1 {
438				t.Errorf("query hook resolved from=%d, want 1", from)
439			}
440			h.firstOnce.Do(func() { close(h.firstParked) })
441			<-h.releaseFirst
442		}
443		restoreAppliedHookLocked = func(newTip int64) {
444			if newTip != h.allowedRestoreTip {
445				t.Errorf("restore hook saw newTip=%d, want %d", newTip, h.allowedRestoreTip)
446			}
447			h.restoreOnce.Do(func() { close(h.restoreParked) })
448			<-h.releaseRestore
449		}
450		t.Cleanup(func() {
451			queryTxsHookLocked = nil
452			restoreAppliedHookLocked = nil
453		})
454		return h
455	}
456	
457	// A first page that has resolved the OLD tip (6) and still holds the lock
458	// when the restore replacement becomes ready must finish on the complete
459	// old chain: records, whole-range totals, matched-block count, and pinned
460	// ToHeight all describe the old chain. The restore applies only afterwards;
461	// the same query then answers from the new chain.
462	func TestQueryTxsInFlightObservesCompleteOldChainBeforeRestore(t *testing.T) {
463		index := buildRestoreQueryOldChain(t)
464		h := installRestoreQueryHooks(t, true, 4)
465		oldChain, newChain := restoreQueryOldChainBlocks(), restoreQueryNewChainBlocks()
466	
467		result := make(chan TxPage, 1)
468		errCh := make(chan error, 1)
469		go func() {
470			page, err := index.QueryTxs(restoreTxQuery)
471			if err != nil {
472				errCh <- err
473				return
474			}
475			result <- page
476		}()
477	
478		<-h.firstParked // query holds index.mu and has pinned the old tip 6
479		restoreDone := make(chan error, 1)
480		go func() {
481			// A fully readable snapshot parses end-to-end and then blocks on
482			// index.mu behind the parked first page.
483			restoreDone <- index.Restore(strings.NewReader(restoreTxNewSnapshot))
484		}()
485	
486		close(h.releaseFirst) // the query scans and finishes on the old chain first
487		var got TxPage
488		select {
489		case got = <-result:
490		case err := <-errCh:
491			t.Fatalf("concurrent query failed: %v", err)
492		}
493		want := restoreReferenceTxPage(oldChain, restoreTxPageSize, 0)
494		if err := classifyTxPage(got, want, restoreReferenceTxPage(newChain, restoreTxPageSize, 0),
495			mustRestoreFilteredHits(t, oldChain), mustRestoreFilteredHits(t, newChain)); err != nil {
496			t.Fatalf("in-flight first page did not return one complete chain:\n%v", err)
497		}
498		if !reflect.DeepEqual(viewOf(got), viewOf(want)) {
499			t.Fatalf("query holding the lock across restore commit must see the old chain:\n%+v", got)
500		}
501		if !reflect.DeepEqual(got.Hits, literalRestoreTxOldFirstPage().Hits) {
502			t.Fatalf("old first page hits=%v, want literal old records", got.Hits)
503		}
504		if got.NextCursor == "" {
505			t.Fatal("old first page over 7 matches must carry a cursor")
506		}
507	
508		close(h.releaseRestore) // the parked restore can now commit and return
509		if err := <-restoreDone; err != nil {
510			t.Fatalf("restore failed: %v", err)
511		}
512		if index.Tip != 4 {
513			t.Fatalf("tip after restore=%d, want 4", index.Tip)
514		}
515	
516		after, err := index.QueryTxs(restoreTxQuery)
517		if err != nil {
518			t.Fatal(err)
519		}
520		if !reflect.DeepEqual(viewOf(after), viewOf(literalRestoreTxNewFirstPage())) {
521			t.Fatalf("query after restore must see the complete new chain:\n%+v", after)
522		}
523	}
524	
525	// A first page issued while a successful restore has already installed the
526	// shorter chain but has not yet returned must wait and then observe the
527	// complete NEW chain: ToHeight follows the new tip (4), every record (with
528	// its block hash and position) is a new-chain record, and totals count the
529	// new range only — never old statistics stitched onto new records.
530	func TestQueryTxsIssuedAtRestoreCommitSeesNewChain(t *testing.T) {
531		index := buildRestoreQueryOldChain(t)
532		h := installRestoreQueryHooks(t, false, 4)
533		oldChain, newChain := restoreQueryOldChainBlocks(), restoreQueryNewChainBlocks()
534	
535		restoreDone := make(chan error, 1)
536		go func() {
537			restoreDone <- index.Restore(strings.NewReader(restoreTxNewSnapshot))
538		}()
539		<-h.restoreParked // new chain installed (tip 4), Restore still holds the lock
540	
541		result := make(chan TxPage, 1)
542		go func() {
543			page, err := index.QueryTxs(restoreTxQuery)
544			if err != nil {
545				t.Errorf("query during restore commit failed: %v", err)
546				return
547			}
548			result <- page
549		}()
550		select {
551		case got := <-result:
552			t.Fatalf("query returned while the restore still held the lock: %+v", got)
553		default:
554		}
555	
556		close(h.releaseRestore)
557		if err := <-restoreDone; err != nil {
558			t.Fatalf("restore failed: %v", err)
559		}
560	
561		got := <-result
562		want := restoreReferenceTxPage(newChain, restoreTxPageSize, 0)
563		if err := classifyTxPage(got, restoreReferenceTxPage(oldChain, restoreTxPageSize, 0), want,
564			mustRestoreFilteredHits(t, oldChain), mustRestoreFilteredHits(t, newChain)); err != nil {
565			t.Fatalf("query across restore commit did not return one complete chain:\n%v", err)
566		}
567		if !reflect.DeepEqual(viewOf(got), viewOf(want)) {
568			t.Fatalf("query after restore commit must see the complete new chain:\n%+v", got)
569		}
570		if !reflect.DeepEqual(got.Hits, literalRestoreTxNewFirstPage().Hits) {
571			t.Fatalf("new first page hits=%v, want literal new records", got.Hits)
572		}
573		if got.ToHeight != 4 || got.TotalMatches != 5 || got.MatchedBlocks != 2 {
574			t.Fatalf("new page must carry new-chain statistics and tip: %+v", got)
575		}
576		for _, hit := range got.Hits {
577			if hit.Height > 4 || strings.HasPrefix(hit.BlockHash, "h") {
578				t.Fatalf("removed-height record leaked into the restore-commit page: %+v", hit)
579			}
580		}
581	
582		// The cursor mints against the new chain and paginates exactly its
583		// filtered occurrences, statistics pinned to the first page throughout.
584		query := restoreTxQuery
585		query.Cursor = got.NextCursor
586		all := append([]TxHit{}, got.Hits...)
587		for pageNo := 1; ; pageNo++ {
588			page, err := index.QueryTxs(query)
589			if err != nil {
590				t.Fatalf("new-chain pagination broke at page %d: %v", pageNo, err)
591			}
592			if page.TotalMatches != 5 || page.MatchedBlocks != 2 || page.ToHeight != 4 {
593				t.Fatalf("page %d statistics drifted from the pinned first page: %+v", pageNo, page)
594			}
595			all = append(all, page.Hits...)
596			if page.NextCursor == "" {
597				break
598			}
599			query.Cursor = page.NextCursor
600		}
601		if wantAll, _ := restoreFilteredHits(newChain, restoreTxQuery.TxIDs); !reflect.DeepEqual(all, wantAll) {
602			t.Fatalf("new-chain pagination=%v, want %v", all, wantAll)
603		}
604	}
605	
606	func mustRestoreFilteredHits(t *testing.T, chain []Block) []TxHit {
607		t.Helper()
608		hits, _ := restoreFilteredHits(chain, restoreTxQuery.TxIDs)
609		return hits
610	}
611	
612	// The complete-chain classifier must reject exactly the mixtures this
613	// regression targets: right-looking records under the other chain's tip or
614	// statistics — including a correctly ordered page stitched from both chains
615	// — while accepting both pure answers.
616	func TestClassifyRestoreTxPageRejectsMixtures(t *testing.T) {
617		oldRef := literalRestoreTxOldFirstPage()
618		newRef := literalRestoreTxNewFirstPage()
619		oldAll := mustRestoreFilteredHits(t, restoreQueryOldChainBlocks())
620		newAll := mustRestoreFilteredHits(t, restoreQueryNewChainBlocks())
621		classify := func(page TxPage) error { return classifyTxPage(page, oldRef, newRef, oldAll, newAll) }
622	
623		if err := classify(oldRef); err != nil {
624			t.Fatalf("pure old page rejected: %v", err)
625		}
626		if err := classify(newRef); err != nil {
627			t.Fatalf("pure new page rejected: %v", err)
628		}
629	
630		// New-chain records and statistics under the stale OLD tip height: looks
631		// internally counted, but claims removed heights 5..6 are in range.
632		mixed := newRef
633		mixed.ToHeight = oldRef.ToHeight
634		if err := classify(mixed); err == nil {
635			t.Fatal("new-chain page under the old tip height was accepted")
636		} else if !strings.Contains(err.Error(), "MIXED") {
637			t.Fatalf("new-records/old-tip mixture not reported as MIXED:\n%v", err)
638		}
639	
640		// Old-chain records and tip with the NEW chain's whole-range statistics:
641		// the records are right for the old chain but totals/blocks came from the
642		// shorter one — the exact "records correct, statistics from the wrong
643		// chain" defect the fixture exists to expose.
644		mixed = oldRef
645		mixed.TotalMatches = newRef.TotalMatches
646		mixed.MatchedBlocks = newRef.MatchedBlocks
647		if err := classify(mixed); err == nil {
648			t.Fatal("old records with new-chain statistics were accepted")
649		} else if !strings.Contains(err.Error(), "MIXED") {
650			t.Fatalf("old-records/new-stats mixture not reported as MIXED:\n%v", err)
651		}
652	
653		// New-chain records and tip with the OLD chain's whole-range statistics.
654		mixed = newRef
655		mixed.TotalMatches = oldRef.TotalMatches
656		mixed.MatchedBlocks = oldRef.MatchedBlocks
657		if err := classify(mixed); err == nil {
658			t.Fatal("new records with old-chain statistics were accepted")
659		} else if !strings.Contains(err.Error(), "MIXED") {
660			t.Fatalf("new-records/old-stats mixture not reported as MIXED:\n%v", err)
661		}
662	
663		// Old-chain page that nevertheless claims the shortened NEW tip: it
664		// counts removed height 5 while promising ToHeight 4.
665		mixed = oldRef
666		mixed.ToHeight = newRef.ToHeight
667		if err := classify(mixed); err == nil {
668			t.Fatal("old records under the new tip height were accepted")
669		} else if !strings.Contains(err.Error(), "MIXED") {
670			t.Fatalf("old-records/new-tip mixture not reported as MIXED:\n%v", err)
671		}
672	
673		// An ordered-looking page that stitches records from both chains:
674		// x@h1 exists only on the old chain (restore replaces height 1 too, so
675		// even the height-1 hashes differ), y@h3 is old-only, and y@j4 is
676		// new-only. Height and position ordering is intact, so ordering-only
677		// checks accept it.
678		mixed = oldRef
679		mixed.Hits = []TxHit{
680			{Height: 1, BlockHash: "h1", TxID: "x", Position: 0}, // old only
681			{Height: 3, BlockHash: "h3", TxID: "y", Position: 1}, // old only
682			{Height: 4, BlockHash: "j4", TxID: "y", Position: 0}, // new only
683		}
684		if err := classify(mixed); err == nil {
685			t.Fatal("stitched hits from both chains were accepted")
686		} else if !strings.Contains(err.Error(), "MIXED") {
687			t.Fatalf("stitched-records mixture not reported as MIXED:\n%v", err)
688		}
689	
690		// Plain corruption: statistics belonging to neither chain.
691		corrupt := newRef
692		corrupt.MatchedBlocks = 99
693		if err := classify(corrupt); err == nil {
694			t.Fatal("corrupt statistics matching neither chain were accepted")
695		} else if !strings.Contains(err.Error(), "CORRUPT") {
696			t.Fatalf("corrupt page not reported as CORRUPT:\n%v", err)
697		}
698	}
699	
700	// Sustained overlap, no hooks: restores alternate between the old-chain
701	// snapshot and the shorter new-chain snapshot while readers issue first
702	// pages continuously. Every page must classify as one complete chain, with
703	// branch identity confirmed record by record; success never depends on
704	// which side of a restore a query happened to land. This supplements the
705	// deterministic rendezvous tests above rather than replacing them.
706	func TestQueryTxsRepeatedRestoresStayConsistent(t *testing.T) {
707		index := buildRestoreQueryOldChain(t)
708		oldChain := restoreQueryOldChainBlocks()
709		newChain := restoreQueryNewChainBlocks()
710		oldSnapshot := exportString(t, index) // version 1: none of the blocks carry times
711		if !strings.Contains(oldSnapshot, `"version":1`) {
712			t.Fatalf("test setup: old snapshot must be version 1: %s", oldSnapshot)
713		}
714		oldRef := restoreReferenceTxPage(oldChain, restoreTxPageSize, 0)
715		newRef := restoreReferenceTxPage(newChain, restoreTxPageSize, 0)
716		oldAll := mustRestoreFilteredHits(t, oldChain)
717		newAll := mustRestoreFilteredHits(t, newChain)
718	
719		const restorers = 2
720		const rounds = 40
721		const readers = 4
722		const reads = 80
723	
724		stop := make(chan struct{})
725		var wg sync.WaitGroup
726		for r := 0; r < restorers; r++ {
727			wg.Add(1)
728			go func(seed int) {
729				defer wg.Done()
730				for i := 0; i < rounds; i++ {
731					select {
732					case <-stop:
733						return
734					default:
735					}
736					snapshot := restoreTxNewSnapshot
737					if (i+seed)%2 == 0 {
738						snapshot = oldSnapshot
739					}
740					if err := index.Restore(strings.NewReader(snapshot)); err != nil {
741						t.Errorf("restore failed: %v", err)
742						return
743					}
744				}
745			}(r)
746		}
747		for r := 0; r < readers; r++ {
748			wg.Add(1)
749			go func() {
750				defer wg.Done()
751				for i := 0; i < reads; i++ {
752					select {
753					case <-stop:
754						return
755					default:
756					}
757					page, err := index.QueryTxs(restoreTxQuery)
758					if err != nil {
759						t.Errorf("first page failed: %v", err)
760						return
761					}
762					var branchHits []TxHit
763					switch page.ToHeight {
764					case 6:
765						branchHits = oldAll
766					case 4:
767						branchHits = newAll
768					default:
769						t.Errorf("first page pinned unknown tip %d", page.ToHeight)
770						return
771					}
772					if err := classifyTxPage(page, oldRef, newRef, oldAll, newAll); err != nil {
773						t.Errorf("%v", err)
774						return
775					}
776					if !reflect.DeepEqual(page.Hits, branchHits[:len(page.Hits)]) {
777						t.Errorf("first page records do not match the pinned branch:\n%+v", page.Hits)
778						return
779					}
780				}
781			}()
782		}
783		wg.Wait()
784		close(stop)
785	
786		// Leave the index deterministically on the shorter new chain and verify
787		// the complete filtered answer, cursor pagination included.
788		if err := index.Restore(strings.NewReader(restoreTxNewSnapshot)); err != nil {
789			t.Fatalf("final restore failed: %v", err)
790		}
791		first, err := index.QueryTxs(restoreTxQuery)
792		if err != nil {
793			t.Fatal(err)
794		}
795		if err := classifyTxPage(first, oldRef, newRef, oldAll, newAll); err != nil {
796			t.Fatalf("final first page is not one complete chain:\n%v", err)
797		}
798		if !reflect.DeepEqual(viewOf(first), viewOf(newRef)) {
799			t.Fatalf("final first page is not the complete new-chain answer:\n%+v", first)
800		}
801		query := restoreTxQuery
802		query.Cursor = first.NextCursor
803		all := append([]TxHit{}, first.Hits...)
804		for query.Cursor != "" {
805			page, err := index.QueryTxs(query)
806			if err != nil {
807				t.Fatalf("final pagination failed: %v", err)
808			}
809			if page.TotalMatches != 5 || page.MatchedBlocks != 2 || page.ToHeight != 4 {
810				t.Fatalf("final pagination statistics drifted: %+v", page)
811			}
812			all = append(all, page.Hits...)
813			query.Cursor = page.NextCursor
814		}
815		if !reflect.DeepEqual(all, newAll) {
816			t.Fatalf("final chain pagination=%v, want %v", all, newAll)
817		}
818	}
819	
820	// A first page pinned to the OLD chain before the restore keeps its semantics
821	// under guard: here the snapshot replaces the whole chain, so the pinned
822	// range [1,6] is no longer covered and the old cursor must fail with
823	// ErrQueryChanged and a zeroed page rather than resume on mixed data.
824	func TestQueryTxsCursorAfterWholeChainRestoreIsChangedAndZeroed(t *testing.T) {
825		index := buildRestoreQueryOldChain(t)
826		first, err := index.QueryTxs(restoreTxQuery)
827		if err != nil {
828			t.Fatal(err)
829		}
830		if first.ToHeight != 6 || first.TotalMatches != 7 || first.NextCursor == "" {
831			t.Fatalf("unexpected first page: %+v", first)
832		}
833	
834		if err := index.Restore(strings.NewReader(restoreTxNewSnapshot)); err != nil {
835			t.Fatalf("restore refused: %v", err)
836		}
837		page, err := index.QueryTxs(TxQuery{
838			TxIDs:    restoreTxQuery.TxIDs,
839			PageSize: restoreTxPageSize,
840			Cursor:   first.NextCursor,
841		})
842		if !errors.Is(err, ErrQueryChanged) {
843			t.Fatalf("old cursor across restore: err=%v page=%+v, want ErrQueryChanged", err, page)
844		}
845		if !reflect.DeepEqual(page, TxPage{}) {
846			t.Fatalf("changed continuation must return a zeroed page, got %+v", page)
847		}
848	}
