package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
)

// halfReader delivers half the bytes together with err in the FIRST read.
type halfReader struct {
	first bool
	data  []byte
	err   error
}

func (r *halfReader) Read(p []byte) (int, error) {
	if !r.first {
		return 0, io.EOF
	}
	r.first = false
	n := copy(p, r.data)
	return n, r.err
}

func main() {
	half := []byte(`{"version":1,"tip":`)

	// 1. clean io.EOF with partial JSON
	dec := json.NewDecoder(&halfReader{first: true, data: half, err: io.EOF})
	_, e := dec.Token()
	fmt.Printf("clean EOF + partial:  err=%v isErrUnexpectedEOF=%v isEOF=%v type=%T\n",
		e, errors.Is(e, io.ErrUnexpectedEOF), errors.Is(e, io.EOF), e)

	// 2. reader-reported io.ErrUnexpectedEOF with partial JSON
	dec = json.NewDecoder(&halfReader{first: true, data: half, err: io.ErrUnexpectedEOF})
	_, e = dec.Token()
	fmt.Printf("fault ErrUnexpectedEOF+partial: err=%v isErrUnexpectedEOF=%v isEOF=%v type=%T\n",
		e, errors.Is(e, io.ErrUnexpectedEOF), errors.Is(e, io.EOF), e)

	// 3. wrapped ErrUnexpectedEOF
	wrapped := fmt.Errorf("storage cut: %w", io.ErrUnexpectedEOF)
	dec = json.NewDecoder(&halfReader{first: true, data: half, err: wrapped})
	_, e = dec.Token()
	fmt.Printf("wrapped fault+partial: err=%v isErrUnexpectedEOF=%v\n", e, errors.Is(e, io.ErrUnexpectedEOF))
}
EOF
