package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"io"
)

// faultRecorder delivers underlying reads but, when the underlying reader
// returns bytes together with a non-EOF fault, reports the bytes as clean and
// replays the fault on the next Read so the decoder cannot drop it in peek.
type faultRecorder struct {
	r       io.Reader
	fault   error
	pending bool
}

func (f *faultRecorder) Read(p []byte) (int, error) {
	if f.pending {
		f.pending = false
		return 0, f.fault
	}
	n, err := f.r.Read(p)
	if err != nil && err != io.EOF && n > 0 {
		f.fault = err
		f.pending = true
		return n, nil
	}
	if err != nil && err != io.EOF {
		f.fault = err
	}
	return n, err
}

type halfReader struct {
	first bool
	data  []byte
	err   error
}

func (r *halfReader) Read(p []byte) (int, error) {
	if !r.first {
		return 0, io.EOF
	}
	r.first = false
	n := copy(p, r.data)
	return n, r.err
}

func drain(dec *json.Decoder) error {
	for {
		_, e := dec.Token()
		if e != nil {
			return e
		}
	}
}

func main() {
	half := []byte(`{"version":1,"tip":`)
	for _, c := range []struct {
		name string
		err  error
	}{
		{"clean EOF", io.EOF},
		{"fault ErrUnexpectedEOF", io.ErrUnexpectedEOF},
		{"wrapped fault", fmt.Errorf("storage cut: %w", io.ErrUnexpectedEOF)},
		{"custom boom", errors.New("boom")},
	} {
		fr := &faultRecorder{r: &halfReader{first: true, data: half, err: c.err}}
		dec := json.NewDecoder(fr)
		e := drain(dec)
		fmt.Printf("%-22s decoderErr=%-30q isUnexpEOF=%-5v recorderFault=%v\n",
			c.name, fmt.Sprint(e), errors.Is(e, io.ErrUnexpectedEOF), fr.fault)
	}
}
