// dripReader delivers its data one byte at a time, so a multi-byte UTF-8
// character is split across several Read calls.
type dripReader struct{ data []byte }

func (r *dripReader) Read(p []byte) (int, error) {
	if len(r.data) == 0 {
		return 0, io.EOF
	}
	p[0] = r.data[0]
	r.data = r.data[1:]
